"""Dedicated stock-count records page; uses the existing Data Center visual theme."""
from data_center_app import DATA_CENTER_HTML

_STYLE = DATA_CENTER_HTML.split('<style>', 1)[1].split('</style>', 1)[0]
STOCK_RECORDS_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock Records · YipMan Work DataCenter</title><style>''' + _STYLE + r'''
header a{color:inherit;text-decoration:none}.records-main{display:flex;flex-direction:column;min-height:calc(100dvh - 44px);gap:10px}.records-nav{display:flex;gap:7px}.records-nav a{border:1px solid var(--line);padding:6px 12px;text-decoration:none;font-size:14px}.records-nav a[aria-current=page]{background:#65ff89;color:#020a05;font-weight:700}.record-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.record-title p{font-size:14px;color:var(--muted);margin-top:4px}.record-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border:1px solid var(--line)}.record-summary>div{padding:9px 12px;border-right:1px solid var(--line)}.record-summary>div:last-child{border-right:0}.record-summary b{font-size:25px;display:block}.record-summary span{font-size:13px;color:var(--muted)}.record-summary .attention{color:var(--warn)}.record-context{display:flex;flex-wrap:wrap;gap:5px 20px;font-size:13px;color:var(--muted)}.record-context b{color:#b1ffc2}.records-pane{display:flex;flex-direction:column;min-height:300px;flex:1;margin:0}.record-tools{display:flex;gap:9px;align-items:center;flex-wrap:wrap;padding-bottom:10px}.record-tabs{display:flex;gap:4px}.record-tabs button{padding:7px 12px;font-size:14px}.record-tabs [aria-pressed=true]{background:#65ff89;color:#020a05}.record-tools select{font:inherit;font-size:14px;padding:8px;border:1px solid var(--line);color:var(--ink);background:#041108}.record-tools input{font-size:15px;margin:0;width:auto;flex:1;min-width:200px}.record-table{flex:1;min-height:180px;max-height:calc(100dvh - 360px)}.record-table table{min-width:920px}.record-table th{font-size:12px;padding:9px}.record-table td{font-size:14px;padding:10px 9px;vertical-align:top}.record-name{font-size:16px;color:#b1ffc2}.record-meta{display:block;color:var(--muted);font-size:12px;margin-top:4px}.stock-value{font-size:21px;font-weight:700;white-space:nowrap}.stock-value small{font-size:12px;font-weight:400}.zero-label{display:inline-block;font-size:11px;border:1px solid #76632b;color:var(--warn);padding:1px 4px;margin-left:5px;white-space:nowrap}.stock-unavailable{color:var(--warn);font-size:14px}.movement-note{display:block;color:var(--muted);font-size:12px;line-height:1.4;margin-top:4px}.record-action{font-size:13px;white-space:nowrap;padding:7px 9px}.record-note{font-size:13px;color:var(--muted);margin-top:7px;max-width:300px;overflow-wrap:anywhere}.record-status{font-size:13px;display:inline-block;color:var(--muted)}.record-status.pending{color:var(--warn)}.record-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:9px;font-size:13px;color:var(--muted)}#message:empty{display:none}.record-empty{padding:40px 15px;text-align:center;color:var(--muted)}.record-empty strong{display:block;font-size:18px;color:var(--ink);margin-bottom:6px}.stock-dialog{width:min(540px,calc(100vw - 28px));background:#041108;color:var(--ink);border:1px solid #65ff89;padding:20px}.stock-dialog::backdrop{background:#000b}.stock-dialog p{font-size:15px;line-height:1.5;margin:12px 0;color:#b1ffc2}.stock-dialog label{font-size:14px;color:var(--muted)}.stock-dialog .dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}.stock-dialog .dialog-error{color:var(--red);font-size:14px;margin-top:8px}.records-help{font-size:13px;color:var(--muted);line-height:1.55;border-left:2px solid #65ff89;padding-left:9px}
@media(min-width:1500px) and (min-height:760px){.records-main{min-height:0}.records-main>*{flex:none}.records-main>.records-pane{flex:1;min-height:0}.record-table{max-height:none;min-height:0}}
@media(max-width:700px){.records-main{gap:8px}.record-title{align-items:flex-start}.record-title h1{font-size:19px}.record-title p{font-size:13px}.record-summary b{font-size:21px}.record-summary>div{padding:7px}.record-summary span{font-size:11px}.record-tools input{flex-basis:100%}.record-table{max-height:60dvh}.records-nav a{font-size:13px}.record-context{font-size:12px}.records-help{font-size:12px}}
</style></head><body>
<header><div><span class="brand-mark" aria-hidden="true">Y</span><strong><a href="/app/data-center">YipMan Work DataCenter</a></strong><span class="brand-divider"></span><small>Store #1032</small></div><div><b>FULL MYSQL</b><small>Stock records</small></div></header>
<main class="records-main">
<nav class="records-nav" aria-label="Data Center pages"><a href="/app/data-center">Data Center</a><a href="/app/stock-records" aria-current="page">Stock Records</a></nav>
<div class="record-title"><div><h1>True Stock &amp; Zero Stock</h1><p>Current effective stock from your counts and subsequent MVT. Review and clear completed dumping tasks.</p></div><button id="refresh">Refresh</button></div>
<div class="record-summary"><div><span>Pending records</span><b id="pendingCount">—</b></div><div><span>Zero stock inputs</span><b id="zeroCount">—</b></div><div><span>Pending dumping</span><b id="dumpCount" class="attention">—</b></div><div><span>History records</span><b id="historyCount">—</b></div></div>
<div class="record-context"><span id="ohReference">Checking latest OH baseline…</span><span id="checked" role="status">Loading records…</span></div>
<div class="records-help">Clearing a record keeps its True Stock adjustment in effect. A new successfully imported OH file replaces earlier counts and clears their pending records. History remains available.</div>
<div id="message" class="notice" role="status"></div>
<section class="panel records-pane" aria-label="Recorded stock inputs"><div class="record-tools"><div class="record-tabs" aria-label="Record view"><button id="pendingTab" aria-pressed="true">Pending</button><button id="historyTab" aria-pressed="false">History</button></div><select id="kind" aria-label="Input type"><option value="all">All inputs</option><option value="zero">Zero stock only</option><option value="count">True Stock only</option></select><input id="search" type="text" placeholder="Search item, article or UPC" aria-label="Search recorded stock" autocomplete="off"></div>
<div id="records" class="scroll record-table"><div class="record-empty">Loading existing records…</div></div><div class="record-bottom"><span id="recordTotal">Effective stock uses completed canonical MVT after the count date.</span><button id="more" hidden>Load more</button></div></section>
<footer>YipMan Work DataCenter DC-9.1 · AS/400 Classic Green · Times shown in your local time.</footer></main>
<dialog id="clearDialog" class="stock-dialog" aria-labelledby="dialogTitle"><h2 id="dialogTitle">Clear record</h2><p id="dialogItem"></p><p id="dialogExplain"></p><label for="clearNote">Note (optional)</label><input id="clearNote" type="text" maxlength="255" placeholder="For example: dumping entered in SAP"><div id="dialogError" class="dialog-error" role="alert"></div><div class="dialog-actions"><button id="cancelClear">Cancel</button><button id="confirmClear" class="primary">Confirm</button></div></dialog>
<script>(()=>{'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v===null||v===undefined?'—':Number(v).toLocaleString(undefined,{maximumFractionDigits:3});
const time=v=>{if(!v)return '—';let s=String(v);return new Date(/Z$|[+-]\d\d:\d\d$/.test(s)?s:s+'Z').toLocaleString()};
const day=v=>v?String(v).slice(0,10):'—';
const signed=v=>(Number(v)>0?'+':'')+number(v);
const blockReasons={MOVEMENT_DAILY_COVERAGE_GAP:'Missing MVT days',UPC_SCOPE_HAS_NO_EXACT_MOVEMENT_KEY:'MVT cannot be matched to this UPC',MOVEMENT_UOM_MISMATCH:'MVT unit mismatch',MOVEMENT_TYPE_UNRESTRICTED_EFFECT_UNRESOLVED:'MVT type needs review'};
function effectiveCell(r){
 const p=r.effective_stock;
 if(!p)return '<span class="record-status">'+(r.record_status==='CANCELLED'?'Count cancelled':'Anchor replaced')+'</span><span class="movement-note">Historical input only</span>';
 const ready=p.analysis_usable&&p.quantity!==null&&p.quantity!==undefined;
 if(!ready){const reasons=(p.blockers||[]).map(b=>blockReasons[b]||b.replace(/_/g,' ').toLowerCase());return '<span class="stock-unavailable">Unavailable</span><span class="movement-note">'+esc(reasons.join(' · ')||'Stock calculation needs review')+'</span>'+(p.missing_movement_day_count?'<span class="movement-note">'+number(p.missing_movement_day_count)+' missing day(s)</span>':'');}
 return '<span class="stock-value">'+number(p.quantity)+' <small>'+esc(p.uom)+'</small></span><span class="movement-note">Net MVT '+signed(p.movement_delta)+' '+esc(p.uom)+'<br>Through '+esc(day(p.movement_through_date))+'</span>';
}
const statuses={PENDING_DUMPING:'Pending dumping',RECORDED:'Recorded',CLEARED:'Cleared',REPLACED_BY_OH:'Replaced by new OH',REPLACED_BY_COUNT:'Replaced by newer count',CANCELLED:'Cancelled'};
let view='pending',rows=[],next=null,total=0,loading=false,sequence=0,controller=null,selected=null,saving=false,searchTimer;
async function api(path,options={}){const response=await fetch(path,{...options,credentials:'same-origin',cache:'no-store'});let data;try{data=await response.json()}catch{throw Error('Service temporarily unavailable ('+response.status+'). Try Refresh.')}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Request failed ('+response.status+')');return data;}
function render(){
 $('pendingTab').setAttribute('aria-pressed',String(view==='pending'));$('historyTab').setAttribute('aria-pressed',String(view==='history'));
 $('records').innerHTML=rows.length?'<table><thead><tr><th>Item / stock scope</th><th>Effective stock</th><th>Recorded input</th><th>Dumping at count</th><th>Recorded at</th><th>Status / action</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><strong class="record-name">'+esc(r.item_name||r.main_article_number||'Unnamed item')+'</strong><span class="record-meta">'+esc(r.scope_type)+' · '+esc(r.article_number||r.main_article_number||r.family_id)+(r.ean_upc?' · UPC '+esc(r.ean_upc):'')+'</span>'+(r.count_note?'<div class="record-note">'+esc(r.count_note)+'</div>':'')+'</td><td>'+effectiveCell(r)+'</td><td>'+number(r.true_stock_quantity)+' '+esc(r.uom_code)+(r.is_zero?'<span class="zero-label">ZERO INPUT</span>':'')+'<span class="record-meta">System then: '+number(r.system_oh_quantity)+' '+esc(r.uom_code)+'</span></td><td>'+number(r.dumping_quantity)+' '+esc(r.uom_code)+'</td><td>'+esc(time(r.submitted_at))+'<span class="record-meta">Record #'+esc(r.true_stock_id)+'</span></td><td><span class="record-status '+(r.can_clear?'pending':'')+'">'+esc(statuses[r.record_status]||r.record_status)+'</span>'+(r.can_clear?'<div style="margin-top:6px"><button class="record-action" data-clear="'+Number(r.true_stock_id)+'">'+(r.record_status==='PENDING_DUMPING'?'Dumping completed':'Clear record')+'</button></div>':'<span class="record-meta">'+esc(time(r.cleared_at||r.superseded_at))+'</span>')+(r.clear_note||r.resolution_note?'<div class="record-note">'+esc(r.clear_note||r.resolution_note)+'</div>':'')+(r.superseded_by_oh_file_id?'<span class="record-meta">OH file #'+esc(r.superseded_by_oh_file_id)+'</span>':'')+'</td></tr>').join('')+'</tbody></table>':'<div class="record-empty"><strong>'+(view==='pending'?'No pending records':'No matching history')+'</strong>'+(view==='pending'?'New True Stock and zero-stock inputs appear here automatically.':'Try another search or input type.')+'</div>';
 $('recordTotal').textContent='Showing '+rows.length+' of '+total+' records · effective stock = recorded input + subsequent completed MVT';$('more').hidden=!next;
 document.querySelectorAll('[data-clear]').forEach(b=>b.onclick=()=>{selected=rows.find(r=>r.true_stock_id===Number(b.dataset.clear));if(!selected)return;$('dialogTitle').textContent=selected.record_status==='PENDING_DUMPING'?'Dumping completed':'Clear record';$('dialogItem').textContent=(selected.item_name||selected.main_article_number)+' · recorded input '+number(selected.true_stock_quantity)+' '+selected.uom_code;$('dialogExplain').textContent=selected.record_status==='PENDING_DUMPING'?'Confirm that this dumping task is finished. The record will move to History; its True Stock adjustment stays active.':'Move this reviewed count to History. Its True Stock adjustment stays active until replaced by a new OH file or another count.';$('clearNote').value='';$('dialogError').textContent='';$('clearDialog').showModal();});
}
async function load(append=false){
 if(loading&&append)return;controller?.abort();controller=new AbortController();const requestController=controller,current=++sequence;loading=true;$('refresh').disabled=true;$('checked').textContent='Updating records…';
 const params=new URLSearchParams({view,kind:$('kind').value,q:$('search').value,limit:'100'});if(append&&next)params.set('before',next);
 const timer=setTimeout(()=>requestController.abort(),15000);
 try{const data=await api('/v1/app/stock-records?'+params,{signal:requestController.signal});if(current!==sequence)return;rows=append?[...rows,...data.rows]:data.rows;next=data.next_before;total=data.total;const c=data.counts||{};$('pendingCount').textContent=c.pending??0;$('zeroCount').textContent=c.zero_pending??0;$('dumpCount').textContent=c.dumping_pending??0;$('historyCount').textContent=c.history??0;const oh=data.latest_oh;$('ohReference').textContent=oh?'OH baseline: '+oh.original_filename+(oh.coverage_end_date?' · '+String(oh.coverage_end_date).slice(0,10):''):'No imported OH baseline found';$('checked').textContent='Checked '+time(data.checked_at)+' · refreshes every 30s';$('message').textContent='';$('message').className='notice';render();}
 catch(e){if(current!==sequence)return;$('message').className='notice bad';$('message').textContent=e.name==='AbortError'?'Update timed out. Previous records remain visible. Use Refresh to retry.':e.message;$('checked').textContent='Update delayed · displayed records may be out of date';}
 finally{clearTimeout(timer);if(current===sequence){loading=false;$('refresh').disabled=false;}}
}
function changeView(v){view=v;next=null;load();}$('pendingTab').onclick=()=>changeView('pending');$('historyTab').onclick=()=>changeView('history');$('kind').onchange=()=>load();$('search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),300)};$('search').onkeydown=e=>{if(e.key==='Enter'){clearTimeout(searchTimer);e.target.blur();load();}};
 $('refresh').onclick=()=>load();$('more').onclick=()=>load(true);$('cancelClear').onclick=()=>{if(!saving)$('clearDialog').close()};$('clearDialog').addEventListener('cancel',e=>{if(saving)e.preventDefault()});
 $('confirmClear').onclick=async()=>{if(saving||!selected)return;saving=true;$('confirmClear').disabled=true;$('cancelClear').disabled=true;$('dialogError').textContent='';try{await api('/v1/app/stock-records/'+selected.true_stock_id+'/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:'CLEAR_STOCK_RECORD',note:$('clearNote').value})});$('clearDialog').close();await load();}catch(e){$('dialogError').textContent=e.message;}finally{saving=false;$('confirmClear').disabled=false;$('cancelClear').disabled=false;}};
 load();setInterval(()=>{if(!document.hidden&&!loading&&!saving&&!$('clearDialog').open)load()},30000);
})();</script></body></html>'''
